import{_ as t,o as e,c as s,ag as n}from"./chunks/framework.-Wrcbzkw.js";const g=JSON.parse('{"title":"RAG 的原理","description":"","frontmatter":{},"headers":[],"relativePath":"LLM/原理/RAG的原理.md","filePath":"LLM/原理/RAG的原理.md","lastUpdated":1781078576000}'),i={name:"LLM/原理/RAG的原理.md"};function p(l,a,d,r,o,h){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="rag-的原理" tabindex="-1">RAG 的原理 <a class="header-anchor" href="#rag-的原理" aria-label="Permalink to &quot;RAG 的原理&quot;">​</a></h1><p>RAG（Retrieval-Augmented Generation，检索增强生成）是一种让大语言模型在回答问题前，先从外部知识库中检索相关资料，再结合资料生成答案的技术。</p><p>它解决的核心问题是：<strong>模型参数中的知识有限、可能过时，而且模型可能在不知道答案时产生幻觉。</strong></p><h2 id="一、rag-的核心思想" tabindex="-1">一、RAG 的核心思想 <a class="header-anchor" href="#一、rag-的核心思想" aria-label="Permalink to &quot;一、RAG 的核心思想&quot;">​</a></h2><p>普通大模型直接根据问题生成答案：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户问题 -&gt; 大语言模型 -&gt; 答案</span></span></code></pre></div><p>RAG 在模型回答前增加了检索过程：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户问题 -&gt; 检索相关资料 -&gt; 将资料和问题交给大模型 -&gt; 答案</span></span></code></pre></div><p>大模型不需要记住全部业务知识，而是像参加开卷考试一样，先查资料，再组织答案。</p><h2 id="二、rag-的完整流程" tabindex="-1">二、RAG 的完整流程 <a class="header-anchor" href="#二、rag-的完整流程" aria-label="Permalink to &quot;二、RAG 的完整流程&quot;">​</a></h2><p>RAG 系统通常分为离线索引和在线问答两个阶段。</p><h3 id="_1-离线索引" tabindex="-1">1. 离线索引 <a class="header-anchor" href="#_1-离线索引" aria-label="Permalink to &quot;1. 离线索引&quot;">​</a></h3><p>离线阶段负责把原始文档转换成可检索的知识库。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原始文档</span></span>
<span class="line"><span>  -&gt; 解析与清洗</span></span>
<span class="line"><span>  -&gt; 文本分块</span></span>
<span class="line"><span>  -&gt; Embedding 向量化</span></span>
<span class="line"><span>  -&gt; 存入向量数据库</span></span></code></pre></div><h4 id="文档解析" tabindex="-1">文档解析 <a class="header-anchor" href="#文档解析" aria-label="Permalink to &quot;文档解析&quot;">​</a></h4><p>系统读取 PDF、网页、Markdown、数据库记录等数据，并保留标题、来源、更新时间和权限等元数据。</p><h4 id="文本分块" tabindex="-1">文本分块 <a class="header-anchor" href="#文本分块" aria-label="Permalink to &quot;文本分块&quot;">​</a></h4><p>Embedding 模型和大模型都有上下文长度限制，因此需要将长文档拆成较小的 Chunk。</p><p>分块太大，会包含过多无关内容；分块太小，又可能破坏完整语义。实际系统通常结合标题、段落、语义边界和一定的重叠区间进行分块。</p><h4 id="embedding-向量化" tabindex="-1">Embedding 向量化 <a class="header-anchor" href="#embedding-向量化" aria-label="Permalink to &quot;Embedding 向量化&quot;">​</a></h4><p>Embedding 模型会把文本映射为高维向量：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;如何重置密码&quot; -&gt; [0.12, -0.38, 0.91, ...]</span></span></code></pre></div><p>语义相近的文本，其向量在空间中的距离也更近。向量数据库保存这些向量及其对应的原文和元数据。</p><h3 id="_2-在线问答" tabindex="-1">2. 在线问答 <a class="header-anchor" href="#_2-在线问答" aria-label="Permalink to &quot;2. 在线问答&quot;">​</a></h3><p>用户提问时，系统执行以下过程：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户问题</span></span>
<span class="line"><span>  -&gt; 问题改写与向量化</span></span>
<span class="line"><span>  -&gt; 召回候选文档</span></span>
<span class="line"><span>  -&gt; 重排序与过滤</span></span>
<span class="line"><span>  -&gt; 组装上下文</span></span>
<span class="line"><span>  -&gt; 大模型生成答案</span></span></code></pre></div><h4 id="查询向量化" tabindex="-1">查询向量化 <a class="header-anchor" href="#查询向量化" aria-label="Permalink to &quot;查询向量化&quot;">​</a></h4><p>系统使用与知识库相同的 Embedding 模型，将用户问题转换为向量。</p><h4 id="相似度检索" tabindex="-1">相似度检索 <a class="header-anchor" href="#相似度检索" aria-label="Permalink to &quot;相似度检索&quot;">​</a></h4><p>向量数据库计算问题向量与文档向量的相似度，常见方法包括余弦相似度、点积和欧氏距离。</p><p>余弦相似度关注两个向量的方向：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cosine_similarity(q, d) = (q · d) / (|q| × |d|)</span></span></code></pre></div><p>相似度越高，通常表示文档与问题越相关。</p><h4 id="重排序" tabindex="-1">重排序 <a class="header-anchor" href="#重排序" aria-label="Permalink to &quot;重排序&quot;">​</a></h4><p>向量检索速度快，但排序不一定足够精确。系统可以使用 Reranker 对候选文档进行二次评分，把真正相关的内容排在前面。</p><h4 id="上下文增强" tabindex="-1">上下文增强 <a class="header-anchor" href="#上下文增强" aria-label="Permalink to &quot;上下文增强&quot;">​</a></h4><p>系统将筛选后的资料和用户问题一起写入 Prompt：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请只根据以下资料回答问题。如果资料不足，请明确说明。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>资料：</span></span>
<span class="line"><span>{retrieved_documents}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>问题：</span></span>
<span class="line"><span>{user_question}</span></span></code></pre></div><p>大模型根据检索到的内容组织答案。需要注意的是，<strong>RAG 并没有临时修改模型参数，只是为本次生成提供了额外上下文。</strong></p><h2 id="三、为什么-rag-有效" tabindex="-1">三、为什么 RAG 有效 <a class="header-anchor" href="#三、为什么-rag-有效" aria-label="Permalink to &quot;三、为什么 RAG 有效&quot;">​</a></h2><p>大语言模型擅长理解语言和组织答案，但不适合仅靠参数保存所有私有、实时知识。RAG 将能力拆分为两个部分：</p><table tabindex="0"><thead><tr><th>组件</th><th>负责的能力</th></tr></thead><tbody><tr><td>检索系统</td><td>找到准确、实时、可追溯的知识</td></tr><tr><td>大语言模型</td><td>理解问题、综合资料、生成自然语言答案</td></tr></tbody></table><p>这种分工使知识可以独立更新，也能在答案中提供资料来源。</p><h2 id="四、rag-与微调的区别" tabindex="-1">四、RAG 与微调的区别 <a class="header-anchor" href="#四、rag-与微调的区别" aria-label="Permalink to &quot;四、RAG 与微调的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>RAG</th><th>微调</th></tr></thead><tbody><tr><td>主要作用</td><td>注入外部知识</td><td>调整模型行为和表达方式</td></tr><tr><td>知识更新</td><td>更新知识库即可</td><td>通常需要重新训练</td></tr><tr><td>可追溯性</td><td>可以引用来源</td><td>很难说明知识来源</td></tr><tr><td>适合场景</td><td>企业知识库、实时资料、文档问答</td><td>固定格式、风格、特定任务能力</td></tr></tbody></table><p>如果目标是让模型知道最新业务资料，优先考虑 RAG；如果目标是让模型稳定遵循特定输出方式，可以考虑微调。两者也可以组合使用。</p><h2 id="五、rag-常见失败原因" tabindex="-1">五、RAG 常见失败原因 <a class="header-anchor" href="#五、rag-常见失败原因" aria-label="Permalink to &quot;五、RAG 常见失败原因&quot;">​</a></h2><p>RAG 的答案质量取决于整条链路，而不只是大模型。</p><ol><li><strong>文档解析失败</strong>：表格、图片或扫描 PDF 中的关键信息没有被正确提取。</li><li><strong>分块不合理</strong>：检索到的片段缺少上下文，无法支持完整答案。</li><li><strong>用户问题表达模糊</strong>：原始问题不适合直接检索，需要查询改写。</li><li><strong>召回不足</strong>：相关文档没有进入候选集合。</li><li><strong>排序错误</strong>：无关内容占据了有限的上下文空间。</li><li><strong>Prompt 约束不足</strong>：模型忽略资料，转而根据参数知识回答。</li><li><strong>知识库内容冲突</strong>：多个版本的资料同时存在，缺少时间或权限过滤。</li></ol><p>因此，评价 RAG 系统时应分别观察召回率、排序质量、上下文相关性、答案忠实度和引用准确性。</p><h2 id="六、常见优化方法" tabindex="-1">六、常见优化方法 <a class="header-anchor" href="#六、常见优化方法" aria-label="Permalink to &quot;六、常见优化方法&quot;">​</a></h2><ul><li>使用语义分块，保留标题和上下文关系</li><li>结合关键词检索与向量检索，形成混合检索</li><li>对用户问题进行改写、拆分或扩展</li><li>使用 Reranker 对召回结果重新排序</li><li>根据用户身份和元数据过滤文档</li><li>要求模型仅基于资料回答，并返回引用来源</li><li>对检索结果和最终答案分别建立评测集</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>RAG 的本质不是让大模型记住更多内容，而是建立一条可靠的“查资料再回答”链路：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>知识入库 -&gt; 问题检索 -&gt; 内容筛选 -&gt; 上下文增强 -&gt; 答案生成</span></span></code></pre></div><p>当资料能够被正确解析、召回和排序时，RAG 可以显著提升回答的准确性、时效性与可追溯性。</p>`,56)])])}const b=t(i,[["render",p]]);export{g as __pageData,b as default};
